#!/usr/bin/env python3
"""P238 Chromium acceptance: in-editor assistant (plan -> approve -> one undo step), offline."""
import functools, http.server, json, os, shutil, socketserver, threading
from playwright.sync_api import sync_playwright
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
class Quiet(http.server.SimpleHTTPRequestHandler):
    def log_message(self, *a): pass
server = socketserver.ThreadingTCPServer(('127.0.0.1', 0), functools.partial(Quiet, directory=ROOT)); server.daemon_threads = True
threading.Thread(target=server.serve_forever, daemon=True).start()
checks = []; errors = []; external = []
def ck(name, ok):
    checks.append((name, bool(ok))); print(('PASS ' if ok else 'FAIL ') + name)
with sync_playwright() as p:
    browser = p.chromium.launch(executable_path=os.environ.get('CHROME_BIN') or shutil.which('google-chrome') or shutil.which('chromium'), headless=True,
        args=['--no-sandbox', '--disable-gpu', '--host-resolver-rules=MAP * ~NOTFOUND , EXCLUDE 127.0.0.1'])
    page = browser.new_page(viewport={'width': 1440, 'height': 900})
    page.on('pageerror', lambda e: errors.append(str(e)))
    page.goto('http://127.0.0.1:%d/index.html' % server.server_address[1], wait_until='domcontentloaded', timeout=120000)
    page.wait_for_function("!!(window.CVAssistantP238&&CVAssistantP238.tests().installed&&window.CVCommandP237&&window.CVNativeStudioShellP234&&CVNativeStudioShellP234.tests().allFourMounted)", timeout=90000)
    for k, v in page.evaluate("CVAssistantP238.tests()").items(): ck('contract ' + k, v)
    ev = page.evaluate
    doc = lambda: ev("CV.poster.snapshotState()")
    layer = lambda i: ev("i=>Object.assign({},CV.poster.doc.layers.find(x=>x.id===i))", i)
    plan = lambda t: ev("t=>CVAssistantP238.plan(t,{ai:false})", t)
    apply_ = lambda i: ev("i=>CVAssistantP238.apply(i)", i)
    ev("CV.go('poster')"); page.wait_for_timeout(700)
    # a slow machine may still be loading the starter design: wait until it stops changing
    page.wait_for_function("(()=>{const s=CV.poster.snapshotState();const same=!!s&&s===window.__s;window.__s=s;return same})()", polling=800, timeout=60000)
    ev("CV.poster.newDesign()"); ev("CV.poster.add('rect')"); rid = ev("CV.poster.selected.id")
    ev("CV.poster.add('text')"); tid = ev("CV.poster.selected.id")
    ev("i=>CV.poster.select(i)", tid)
    btn = page.locator('#page-poster .cv238-open')
    ck('assistant button is visible in the Poster toolbar', btn.is_visible())
    btn.click(); page.wait_for_timeout(400)
    box = page.locator('#cv238 textarea')
    ck('panel opens with the selected object', page.locator('#cv238').is_visible() and 'TIÊU ĐỀ MỚI' in page.locator('#cv238 .ctx b').inner_text())
    ck('panel shows Brand Kit swatches', page.locator('#cv238 .kit i').count() == 4)
    ck('panel sits fully on screen and on the right', ev("(()=>{const r=document.querySelector('#cv238').getBoundingClientRect();return r.right<=innerWidth&&r.bottom<=innerHeight&&r.top>=0&&r.left>innerWidth/2})()"))
    ck('panel is the top element where it is drawn', ev("(()=>{const e=document.querySelector('#cv238'),r=e.getBoundingClientRect();return [.1,.5,.9].every(f=>e.contains(document.elementFromPoint(r.x+r.width*.5,r.y+r.height*f)))})()"))
    before = doc(); old = layer(tid); n = ev("CV.poster.doc.layers.length")
    box.fill(''); box.press_sequentially('chu to hon'); box.press('Backspace'); box.press('Delete')
    ck('typing and deleting in the chat never edits the poster', doc() == before and ev("CV.poster.doc.layers.length") == n)
    box.fill('chữ to hơn, màu đỏ, căn giữa'); box.press('Enter'); page.wait_for_selector('#cv238 [data-cv238=apply]')
    ck('a plan is shown and nothing changes before approval', doc() == before and page.locator('#cv238 .msg.plan li').count() >= 3)
    page.locator('#cv238 [data-cv238=apply]').click(); page.wait_for_timeout(300)
    new = layer(tid)
    ck('approved plan changes size, colour and position', new['size'] == round(old['size'] * 1.2) and new['color'] == '#e11d48' and new['align'] == 'center' and abs(new['x'] - (ev("CV.poster.doc.w") - new['w']) / 2) <= 1)
    a, b = json.loads(before), json.loads(doc())
    ck('only the selected object changed', [x for x in a['layers'] if x['id'] != tid] == [x for x in b['layers'] if x['id'] != tid])
    ck('selection is kept after apply', ev("CV.poster.selected&&CV.poster.selected.id") == tid)
    ck('inspector reflects the new colour', ev("document.getElementById('pColor').value") == '#e11d48')
    ev("CV.poster.history.undo()")
    ck('one editor undo reverts the whole plan', doc() == before)
    ev("CV.poster.history.redo()"); ck('redo restores the whole plan', layer(tid) == new)
    ev("CV.poster.history.undo();"); ev("i=>CV.poster.select(i)", tid)
    r = plan('đổi chữ thành "Khai trương Rực Rỡ, giảm 50%"'); apply_(r['id'])
    ck('rewrite keeps quoted text exactly, commas included', layer(tid)['text'] == 'Khai trương Rực Rỡ, giảm 50%' and layer(tid)['color'] == old['color'])
    u = ev("i=>CVAssistantP238.undo(i)", r['id']); ck('panel undo reverts its own plan', u['ok'] and doc() == before)
    ev("i=>CV.poster.select(i)", tid)
    r = plan('đổi chữ thành màu xanh lá'); apply_(r['id'])
    ck('colour phrased as "đổi chữ thành màu" is not treated as wording', layer(tid)['color'] == '#16a34a' and layer(tid)['text'] == old['text'])
    ev("CV.poster.add('ellipse')"); u = ev("i=>CVAssistantP238.undo(i)", r['id'])
    ck('panel undo refuses after a newer edit', not u['ok'] and layer(tid)['color'] == '#16a34a')
    ev("i=>CV.poster.select(i)", tid)
    r = plan('viết hoa và bỏ đậm'); apply_(r['id']); ck('upper case and weight rules', layer(tid)['text'] == old['text'].upper() and layer(tid)['weight'] == 400)
    r = plan('cỡ chữ 48, font có chân, độ mờ 60%'); apply_(r['id']); L = layer(tid)
    ck('absolute size, font and opacity rules', L['size'] == 48 and L['font'] == 'serif' and L['opacity'] == 0.6)
    brand = ev("CVAssistantP238.context('').brand")
    r = plan('áp brand kit'); apply_(r['id']); ck('Brand Kit applies to the selected text', layer(tid)['color'] == brand['primary'])
    ev("i=>CV.poster.select(i)", rid); r = plan('nền màu vàng, bo góc'); apply_(r['id'])
    ck('shape colour and corner radius', layer(rid)['bg'] == '#facc15' and layer(rid)['radius'] == 24)
    r = plan('chữ to hơn'); ck('text-only request on a shape is refused', not r['ok'])
    snap = doc(); r = plan('tất cả chữ màu tím')
    texts = [x['id'] for x in json.loads(snap)['layers'] if x['type'] in ('text', 'badge')]
    ck('"tất cả chữ" plans only text objects', r['ok'] and sorted({x['id'] for x in r['plan']['actions']}) == sorted(texts))
    ev("CV.poster.select(null)"); r = plan('màu đỏ'); ck('no selection asks the user to pick an object', not r['ok'] and 'chọn' in r['reason'])
    ev("i=>CV.poster.select(i)", tid); ev("i=>CV.poster.setLayerLocked(i,true)", tid); ev("i=>CV.poster.select(i)", tid)
    r = plan('tất cả màu đỏ'); ck('locked objects are left out of "tất cả"', r['ok'] and tid not in [x['id'] for x in r['plan']['actions']])
    ev("i=>CV.poster.setLayerLocked(i,false)", tid); ev("i=>CV.poster.select(i)", tid)
    r = plan('màu cam'); ev("i=>CV.poster.setLayerLocked(i,true)", tid); res = apply_(r['id'])
    ck('object locked after planning is not changed', not res['ok'] and layer(tid)['color'] != '#f97316')
    ev("i=>CV.poster.setLayerLocked(i,false)", tid); ev("i=>CV.poster.select(i)", tid)
    r = plan('màu cam'); ev("i=>CV.poster.setLayerLocked(i,false)", rid); ev("(i)=>{CV.poster.doc.layers.find(x=>x.id===i).x+=5}", tid); res = apply_(r['id'])
    ck('stale plan is rejected', not res['ok'])
    r = plan('màu cam'); ev("CVAssistantP238.discard()"); res = apply_(r['id']); ck('discarded plan cannot be applied', not res['ok'])
    r = plan('màu cam'); apply_(r['id']); res = apply_(r['id']); ck('a plan applies only once', not res['ok'])
    r = plan('hãy làm cho nó thật nghệ thuật'); ck('unknown request makes no plan and no change', not r['ok'])
    r = plan('màu đỏ, bay lên mặt trăng'); ck('partly understood request names the ignored part', r['ok'] and r['unknown'] == ['bay len mat trang'])
    # bad plans are rejected as a whole, atomically
    bad = {
        'not an object': 'null', 'no actions': '({actions:[]})', 'unknown op': "({actions:[{op:'deleteAll',id:I}]})",
        'prototype op': "({actions:[{op:'constructor',id:I,value:1}]})", 'foreign id': "({actions:[{op:'setColor',id:R,value:'#000000'}]})",
        'extra field': "({actions:[{op:'setColor',id:I,value:'#000000',src:'x'}]})", 'css injection': "({actions:[{op:'setColor',id:I,value:'red;background:url(x)'}]})",
        'wrong type': "({actions:[{op:'setSize',id:I,value:'48'}]})", 'out of range': "({actions:[{op:'setSize',id:I,value:99999}]})",
        'op for another type': "({actions:[{op:'setBg',id:I,value:'#000000'}]})", 'one bad among good': "({actions:[{op:'setColor',id:I,value:'#000000'},{op:'setSize',id:I,value:-1}]})",
        'too many': "({actions:Array.from({length:41},()=>({op:'setColor',id:I,value:'#000000'}))})"}
    ev("i=>CV.poster.select(i)", tid); snap = doc()
    for name, js in bad.items():
        ck('rejects ' + name, ev("([I,R])=>CVAssistantP238.validate(%s,CVAssistantP238.context('')).ok===false" % js, [tid, rid]))
    ck('rejected plans leave the document untouched', doc() == snap)
    # AI tier: opt-in, same validator, fake provider
    ev("""()=>{window.__aiCalls=0;CVOrchestratorP128.clearCache();CVOrchestratorP128.setOrder('local-only');CVOrchestratorP128.register('text','local',()=>{window.__aiCalls++;return window.__ai})}""")
    r = plan('cho nó sang trọng'); ck('AI is not called unless enabled', not r['ok'] and ev("__aiCalls") == 0)
    ev("i=>{window.__ai='Đây: ```json\\n{\"actions\":[{\"op\":\"setColor\",\"id\":\"'+i+'\",\"value\":\"#bfa14a\"}]}\\n```'}", tid)
    r = ev("CVAssistantP238.plan('cho nó sang trọng',{ai:true})"); ck('valid AI plan is offered for approval only', r['ok'] and r['source'].startswith('AI') and doc() == snap)
    apply_(r['id']); ck('approved AI plan applies', layer(tid)['color'] == '#bfa14a')
    snap = doc(); ev("()=>{window.__ai='{\"actions\":[{\"op\":\"remove\",\"id\":\"x\"}]}'}")
    r = ev("CVAssistantP238.plan('cho nó sang trọng',{ai:true})"); ck('malicious AI plan is rejected safely', not r['ok'] and doc() == snap)
    ev("()=>{window.__ai='xin lỗi, tôi không làm được'}"); r = ev("CVAssistantP238.plan('cho nó sang trọng',{ai:true})"); ck('non-JSON AI answer is rejected safely', not r['ok'] and doc() == snap)
    # chat renders user text as text, offers editor commands instead of running them
    box.fill('<img src=x onerror="window.__x=1">'); box.press('Enter'); page.wait_for_timeout(300)
    ck('user text is never parsed as HTML', ev("!window.__x&&!document.querySelector('#cv238 .log img')"))
    n = ev("CV.poster.doc.layers.length"); box.fill('thêm hình tròn'); box.press('Enter'); page.wait_for_selector('#cv238 [data-cv238=command]')
    ck('editor command waits for approval', ev("CV.poster.doc.layers.length") == n)
    page.locator('#cv238 [data-cv238=command]').click(); page.wait_for_timeout(600); ck('approved editor command runs once', ev("CV.poster.doc.layers.length") == n + 1)
    ev("i=>CV.poster.select(i)", tid); box.fill('màu hồng'); box.press('Enter'); page.wait_for_selector('#cv238 [data-cv238=apply]:not([disabled])')
    snap = doc(); page.locator('#cv238 [data-cv238=discard]:not([disabled])').click(); ck('Bỏ keeps the design', doc() == snap)
    page.screenshot(path=os.environ.get('P238_SHOT', '/tmp/p238-poster.png'))
    box.press('Escape'); ck('Escape closes the panel', not page.locator('#cv238').is_visible())
    # Video Engine
    btn.click(); ev("CV.go('videoEngine')"); page.wait_for_timeout(900)
    vbtn = page.locator('#page-videoEngine .cv238-open')
    ck('assistant button is visible in Video Engine', vbtn.is_visible())
    ev("CV.engines.video.addText()"); vid = ev("CV.engines.video._state().selected")
    clip = lambda: ev("i=>{const c=Object.assign({},CV.engines.video._state().clips.find(x=>x.id===i));delete c.el;return c}", vid)
    clips = lambda: ev("JSON.stringify(CV.engines.video._state().clips)")
    if not page.locator('#cv238').is_visible(): vbtn.click()
    page.wait_for_timeout(700)
    ck('video panel names the selected clip', 'Text overlay' in page.locator('#cv238 .ctx b').inner_text())
    ck('switching editor starts a clean conversation', page.locator('#cv238 .msg.plan').count() == 0 and page.locator('#cv238 .msg.me').count() == 0)
    ratio = """s=>{const c=getComputedStyle(document.querySelector(s));const L=v=>{const m=v.match(/[\\d.]+/g).slice(0,3).map(x=>{x/=255;return x<=.03928?x/12.92:Math.pow((x+.055)/1.055,2.4)});return .2126*m[0]+.7152*m[1]+.0722*m[2]},x=L(c.color),y=L(c.backgroundColor);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05)}"""
    ck('toolbar button text is readable and marked open', ev(ratio, '#page-videoEngine .cv238-open') >= 4.5 and ev("(()=>{const b=document.querySelector('#page-videoEngine .cv238-open');return parseFloat(getComputedStyle(b,'::after').fontSize)>=12&&b.offsetWidth>=60&&b.scrollWidth<=b.clientWidth+1&&b.getAttribute('aria-expanded')==='true'})()"))
    ck('send button text is readable', ev(ratio, '#cv238 form button') >= 4.5)
    ck('first-use hint does not cover the panel', ev("[...document.querySelectorAll('.cv236-first-use')].every(n=>!n.offsetWidth)"))
    ck('video toolbar button shares the tool row', ev("(()=>{const a=document.querySelector('#page-videoEngine .cv238-open').getBoundingClientRect(),b=document.querySelector('#page-videoEngine [data-cv231-action=toggle-rail]').getBoundingClientRect();return Math.abs(a.y-b.y)<6})()"))
    v0 = clip(); s0 = clips()
    box.fill('đổi chữ thành Xin chào CANVIO, dài 8 giây'); box.press('Enter'); page.wait_for_selector('#cv238 [data-cv238=apply]:not([disabled])')
    ck('unquoted wording stops before a following instruction', [(a['op'], a['value']) for a in plan('đổi chữ thành Xin chào CANVIO, dài 8 giây')['plan']['actions']] == [('setText', 'Xin chào CANVIO'), ('setDuration', 8)])
    ck('unquoted wording keeps its own commas', plan('đổi chữ thành Trà, cà phê và bánh')['plan']['actions'][0]['value'] == 'Trà, cà phê và bánh')
    r = plan('đổi chữ thành "Xin chào CANVIO", dài 8 giây, bắt đầu ở giây 2')
    ck('video plan waits for approval', r['ok'] and clips() == s0)
    res = apply_(r['id']); v1 = clip()
    ck('video plan sets text, length and start', res['ok'] and v1['text'] == 'Xin chào CANVIO' and v1['duration'] == 8 and v1['start'] == 2)
    ev("CV.engines.video.undo()"); ck('one video undo reverts the whole plan', clip() == v0)
    ev("i=>CV.engines.video.select(i)", vid); r = plan('dài hơn 2 giây'); apply_(r['id']); u = ev("i=>CVAssistantP238.undo(i)", r['id'])
    ck('video panel undo works', u['ok'] and clip()['duration'] == v0['duration'])
    ev("i=>CV.engines.video.select(i)", vid); r = plan('đổi tên thành Mở đầu'); apply_(r['id']); ck('rename clip', clip()['name'] == 'Mở đầu' and clip()['text'] == v0['text'])
    r = plan('màu đỏ'); ck('unsupported video request is refused', not r['ok'])
    s = clips(); ck('video validator blocks other fields', ev("i=>CVAssistantP238.validate({actions:[{op:'setColor',id:i,value:'#000000'}]},CVAssistantP238.context('')).ok===false", vid) and clips() == s)
    ev("CV.engines.video.toggleTrack(3,'locked')"); r = plan('dài 9 giây'); ck('locked track is refused', not r['ok'] and clip()['duration'] != 9); ev("CV.engines.video.toggleTrack(3,'locked')")
    page.screenshot(path=os.environ.get('P238_SHOT_V', '/tmp/p238-video.png'))
    ev("CV.go('home')"); page.wait_for_timeout(500); ck('panel closes when leaving the editors', not page.locator('#cv238').is_visible())
    for width in (390, 320):
        page.set_viewport_size({'width': width, 'height': 844}); ev("CV.go('poster')"); page.wait_for_timeout(800)
        b = page.locator('#page-poster .cv238-open'); b.scroll_into_view_if_needed()
        ck('assistant button reachable at %dpx' % width, b.is_visible() and ev("(()=>{const r=document.querySelector('#page-poster .cv238-open').getBoundingClientRect();return r.left>=0&&r.right<=innerWidth})()"))
        b.click(); page.wait_for_timeout(400)
        ck('panel and send button fit at %dpx' % width, ev("(()=>{return ['#cv238','#cv238 form button','#cv238 textarea'].every(s=>{const r=document.querySelector(s).getBoundingClientRect();return r.left>=0&&r.right<=innerWidth&&r.top>=0&&r.bottom<=innerHeight&&r.height>0})})()"))
        page.screenshot(path='/tmp/p238-%d.png' % width)
        page.locator('#cv238 [data-cv238=close]').click()
    ck('No uncaught JavaScript page errors', not errors)
    if errors: print('PAGE_ERRORS ' + repr(errors))
    browser.close()
server.shutdown(); server.server_close()
failed = [n for n, v in checks if not v]
print('%d/%d P238 browser assertions passed' % (len(checks) - len(failed), len(checks)))
if failed: raise SystemExit('Failures: ' + ', '.join(failed))
